// SENTINEL FX by Greg Ballerz (GB_FX) - 8-agent signal desk, single-file version for easy upload (phone friendly).
// The desk files are stored compressed below; on start they are unpacked into ./app and run. Nothing to install.
// Full readable source: Sentinel_FX_Full_Source.zip
const fs = require('fs'), path = require('path'), zlib = require('zlib');
const FILES = JSON.parse(zlib.gunzipSync(Buffer.from('', 'base64')).toString('utf8'));
const dir = path.join(__dirname, 'app');
for (const [rel, body] of Object.entries(FILES)) {
  const f = path.join(dir, rel);
  fs.mkdirSync(path.dirname(f), { recursive: true });
  fs.writeFileSync(f, typeof body === 'string' ? body : Buffer.from(body.b64, 'base64'));
}
require(path.join(dir, 'server.js'));
